function essentials(){return state.habits.filter(h=>h.essential)}
function dayScore(date){const hs=essentials();if(!hs.length)return 0;const rec=state.records[date];if(!rec)return 0;const habitScore=hs.filter(h=>rec.habits?.[h.id]).length/hs.length;if(normalizeFaith(state.profile.faith)!=="islam")return habitScore;const prayers=["Fajr","Dhuhr","Asr","Maghrib","Isha"];const prayerScore=prayers.filter(n=>!!rec.prayers?.[n]).length/prayers.length;return (habitScore+prayerScore)/2}
function isPerfectDay(date){const hs=essentials();const rec=state.records[date];if(!hs.length||!rec||!hs.every(h=>!!rec.habits?.[h.id]))return false;if(normalizeFaith(state.profile.faith)==="islam")return ["Fajr","Dhuhr","Asr","Maghrib","Isha"].every(n=>!!rec.prayers?.[n]);return true}
function isQualifyingDay(date){return dayScore(date)>=.8}
function startOfWeek(d){const x=new Date(d);x.setHours(12,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}
function weekDates(d=new Date()){const start=startOfWeek(d);return Array.from({length:7},(_,i)=>{const x=new Date(start);x.setDate(start.getDate()+i);return x})}
