function currentStreak(){let d=dateFromISO(today),n=0;for(let i=0;i<3660;i++){const s=isoDate(d);if(!isQualifyingDay(s))break;n++;d.setDate(d.getDate()-1)}return n}
function bestStreak(){const dates=Object.keys(state.records).filter(d=>Object.keys(state.records[d]?.habits||{}).length).sort();let best=0,run=0,prev=null;for(const s of dates){if(!isQualifyingDay(s)){run=0;prev=s;continue}const d=dateFromISO(s);if(prev){const p=dateFromISO(prev);const gap=(d-p)/86400000;run=gap===1?run+1:1}else run=1;best=Math.max(best,run);prev=s}return best}
