function buildMotivation(){const outcomes=(state.routineOutcomes||[]).filter(x=>x.date>=isoDate(new Date(Date.now()-6*86400000))).sort((a,b)=>(b.respondedAt||"").localeCompare(a.respondedAt||""));const missed=outcomes.filter(x=>x.status==="missed").length,done=outcomes.filter(x=>x.status==="completed").length;const scenarios=[];if(missed>=3)scenarios.push("A few plans didn't happen this week. That is information, not a verdict. Try making one of them smaller or moving it to a kinder time.");if(missed>0&&done>missed)scenarios.push("You have followed through more often than not lately. Keep what is working, and make the difficult bits easier rather than stricter.");if(missed>0&&done===0)scenarios.push("This week may have asked a lot of you. Pick one useful thing to make easier today; you do not need to repair the whole week at once.");if(done>=4)scenarios.push("Your small actions are adding up. Notice which routines fit naturally, and give yourself credit for showing up.");if(outcomes.length===0)scenarios.push("You don't have to do everything. Just the next kind thing.","Small steps count, even when nobody sees them.","You can begin again without starting from zero.","Rest is part of a life, not a break from it.");if(missed===1)scenarios.push("One missed plan doesn't erase the rest of your effort. If it still matters, try a smaller version or a different time.");if(done>0&&missed===0)scenarios.push("You have been showing up for the things you chose. Keep your routine realistic enough to live with, not just admire.");const pool=scenarios.length?scenarios:["Progress can be quiet. Choose one thing that would make today feel a little more manageable.","Your routine is here to support your life, not judge it. Adjust it when life changes."];const idx=Math.abs(new Date().getDate()+done*3+missed*7)%pool.length;return pool[idx]}
